// 考研政治背诵知识框架
const FrameworkData = '<div class="fw-book open" id="book0">\n  <div class="fw-book-header" onclick="document.getElementById(\'book0\').classList.toggle(\'open\')">\n    <span class="fw-arrow">▶</span>\n    <span class="fw-book-icon" style="background:#e74c3c">📕</span>\n    <span class="fw-book-title">第一篇：马克思主义基本原理</span>\n    <span class="fw-book-badge">8章</span>\n  </div>\n  <div class="fw-book-content">\n    <div class="fw-toolbar">\n      <button class="on" onclick="toggleAll(\'book0\',true,this)">展开全部</button>\n      <button onclick="toggleAll(\'book0\',false,this)">收起全部</button>\n    </div>\n    <div class="fw-tree">\n\n      <div class="fw-chapter" id="b0c0">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c0\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          导论\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c0s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c0s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、什么是马克思主义\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">马克思主义 = 马克思、恩格斯创立 + 后继者不断发展的<strong>科学理论体系<strong></div>\n              <div class="fw-bullet">三个基本组成部分：<strong>马克思主义哲学<strong> + <strong>马克思主义政治经济学<strong> + <strong>科学社会主义<strong></div>\n              <div class="fw-bullet">马克思主义基本原理 = <strong>基本立场 + 基本观点 + 基本方法<strong>的有机统一</div>\n              <div class="fw-bullet">基本立场：以人民为中心，无产阶级解放 + 全人类解放</div>\n              <div class="fw-bullet">基本方法：实事求是、辩证分析、矛盾分析、历史分析、阶级分析、群众路线</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c0s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c0s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、马克思主义的创立与发展\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">创立时间：<strong>19世纪40年代<strong>，创始人：马克思、恩格斯</div>\n              <div class="fw-bullet">三大理论来源：<strong>德国古典哲学<strong>(辩证法) + <strong>英国古典政治经济学<strong>(劳动价值论) + <strong>英法空想社会主义<strong></div>\n              <div class="fw-bullet">三大自然科学前提：细胞学说 + 能量守恒转化定律 + 生物进化论</div>\n              <div class="fw-bullet">诞生标志：<strong>1848年《共产党宣言》<strong>发表</div>\n              <div class="fw-bullet">马克思两大发现：<strong>唯物史观<strong> + <strong>剩余价值学说<strong>，使社会主义从空想变科学</div>\n              <div class="fw-bullet">列宁主义：帝国主义阶段 -> 一国或数国首先胜利论 -> 十月革命(1917)</div>\n              <div class="fw-bullet">马克思主义中国化时代化三次飞跃：<strong>毛泽东思想<strong> -> <strong>中国特色社会主义理论体系<strong> -> <strong>习近平新时代中国特色社会主义思想<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c0s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c0s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、马克思主义的基本特征\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>科学性<strong>：正确反映规律；辩证唯物主义+历史唯物主义为基础</div>\n              <div class="fw-bullet"><strong>人民性<strong>：人民至上；无产阶级解放 = 全人类解放</div>\n              <div class="fw-bullet"><strong>实践性<strong>：首要和基本的观点是<strong>实践观点<strong></div>\n              <div class="fw-bullet"><strong>发展性<strong>：与时俱进；开放的理论体系</div>\n              <div class="fw-bullet"><strong>总概括<strong>：科学性与革命性的统一</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c0s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c0s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、马克思主义的当代价值\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">观察当代世界变化的<strong>认识工具<strong></div>\n              <div class="fw-bullet">指引当代中国发展的<strong>行动指南<strong></div>\n              <div class="fw-bullet">引领人类社会进步的<strong>科学真理<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c1">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c1\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第一章 世界的物质性及发展规律\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c1s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c1s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 世界的多样性与物质统一性\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c1s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、物质及其存在方式\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">哲学基本问题：<strong>存在和思维的关系<strong> = 物质vs精神何者为第一性 + 思维能否认识存在</div>\n                  <div class="fw-bullet">唯物主义(物质第一性) vs 唯心主义(意识第一性)；可知论 vs 不可知论</div>\n                  <div class="fw-bullet">列宁物质定义：<strong>不依赖于感觉而存在、为感觉所复写的客观实在<strong></div>\n                  <div class="fw-bullet">物质根本属性：<strong>运动<strong>(无条件、绝对)；静止是运动特殊状态(有条件、相对)</div>\n                  <div class="fw-bullet">物质运动存在形式：<strong>时间<strong>(一维性)和<strong>空间<strong>(三维性)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c1s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、物质与意识的辩证关系\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>物质决定意识<strong>：意识是人脑机能，是客观世界的主观映象</div>\n                  <div class="fw-bullet"><strong>意识反作用于物质<strong>：目的性、创造性、指导实践、调控生理</div>\n                  <div class="fw-bullet">主观能动性与客观规律性辩证统一：<strong>尊重客观规律是前提<strong></div>\n                  <div class="fw-bullet">人工智能：人类意识的物化和模拟，<strong>不能取代和超越人类意识<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c1s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、世界的物质统一性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">世界的统一性在于<strong>物质性<strong>：自然+人类社会+意识都统一于物质</div>\n                  <div class="fw-bullet">意义：一切从实际出发，实事求是，马克思主义世界观的<strong>基石<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c1s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c1s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 事物的普遍联系和变化发展\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c1s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、联系和发展的普遍性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>联系<strong>：事物内部和事物之间相互影响、制约、作用的关系</div>\n                  <div class="fw-bullet">联系的特点：<strong>客观性、普遍性、多样性、条件性<strong></div>\n                  <div class="fw-bullet"><strong>发展<strong>：前进的上升的运动，实质是<strong>新事物产生、旧事物灭亡<strong></div>\n                  <div class="fw-bullet">新事物不可战胜：适应新环境 + 扬弃旧事物 + 符合人民利益</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c1s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、对立统一规律是事物发展的根本规律\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">对立统一规律是唯物辩证法的<strong>实质和核心<strong></div>\n                  <div class="fw-bullet">矛盾 = 既对立又统一：<strong>同一性<strong>(依存/贯通) + <strong>斗争性<strong>(排斥/否定)</div>\n                  <div class="fw-bullet">矛盾<strong>普遍性<strong>(无处不在) vs <strong>特殊性<strong>(各有特点)</div>\n                  <div class="fw-bullet">矛盾问题<strong>精髓<strong>：共性和个性、绝对和相对的关系</div>\n                  <div class="fw-bullet">主要矛盾vs次要矛盾 + 矛盾主次方面 -> <strong>两点论+重点论<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c1s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、量变质变规律和否定之否定规律\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">量变(数量变化) -> 质变(根本性质变化) -> 新量变</div>\n                  <div class="fw-bullet">否定之否定：自我否定 -> <strong>螺旋式上升、波浪式前进<strong></div>\n                  <div class="fw-bullet">辩证否定观：<strong>自我否定 + 发展环节 + 联系环节<strong>，实质是"扬弃"</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c1s1sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s1sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、联系和发展的基本环节\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>内容与形式<strong>：内容决定形式，形式反作用于内容</div>\n                  <div class="fw-bullet"><strong>现象与本质<strong>：透过现象看本质</div>\n                  <div class="fw-bullet"><strong>原因与结果<strong>：因果联系客观、普遍、辩证</div>\n                  <div class="fw-bullet"><strong>必然与偶然<strong>：必然通过偶然表现并开辟道路</div>\n                  <div class="fw-bullet"><strong>现实与可能<strong>：区分可能与不可能、现实可能与抽象可能</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c1s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c1s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 唯物辩证法是认识世界和改造世界的根本方法\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c1s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、唯物辩证法的本质特征和认识功能\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">本质特征：<strong>批判的、革命的<strong></div>\n                  <div class="fw-bullet">客观辩证法 vs 主观辩证法：主观辩证法是客观辩证法的反映</div>\n                  <div class="fw-bullet">辩证思维方法：归纳与演绎、分析与综合、抽象与具体、逻辑与历史相统一</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c1s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c1s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、学习唯物辩证法，不断增强思维能力\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>辩证思维<strong>：承认矛盾、分析矛盾、解决矛盾</div>\n                  <div class="fw-bullet"><strong>历史思维<strong>：以史为鉴、知古鉴今</div>\n                  <div class="fw-bullet"><strong>系统思维<strong>：整体性、结构性、层次性、开放性</div>\n                  <div class="fw-bullet"><strong>战略思维<strong>：高瞻远瞩、统揽全局</div>\n                  <div class="fw-bullet"><strong>底线思维<strong>：设定最低目标，争取最好结果</div>\n                  <div class="fw-bullet"><strong>创新思维<strong>：破除迷信，超越陈规</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c2">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c2\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第二章 实践与认识及其发展规律\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c2s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c2s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 实践与认识\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c2s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、科学的实践观及其意义\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">实践性是马克思主义区别于其他理论的<strong>根本特征<strong></div>\n                  <div class="fw-bullet">实践三特征：<strong>客观实在性 + 自觉能动性 + 社会历史性<strong></div>\n                  <div class="fw-bullet">实践基本结构：<strong>主体 + 客体 + 中介<strong></div>\n                  <div class="fw-bullet">实践基本类型：物质生产实践(最基本)、社会政治实践、科学文化实践</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、实践的本质与基本结构\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">主体客体化(主体->客体)和客体主体化(客体->主体)</div>\n                  <div class="fw-bullet">实践中介：物质性工具 + 语言符号</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、认识的本质与过程\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">认识的本质：<strong>主体在实践基础上对客体的能动反映<strong></div>\n                  <div class="fw-bullet">两次飞跃：<strong>感性认识->理性认识<strong>(第一次) -> <strong>理性认识->实践<strong>(第二次，更重要)</div>\n                  <div class="fw-bullet">感性认识(感觉/知觉/表象) vs 理性认识(概念/判断/推理)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s0sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s0sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、实践与认识的辩证运动及其规律\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">实践->认识->再实践->再认识，循环往复以至无穷</div>\n                  <div class="fw-bullet">实践对认识的决定作用：<strong>来源、动力、目的、检验标准<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c2s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c2s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 真理与价值\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c2s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、真理的客观性、绝对性和相对性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">真理：<strong>主观与客观相符合<strong>，对客观事物及规律的正确反映</div>\n                  <div class="fw-bullet">真理客观性：内容客观、标准(实践)客观；<strong>真理没有阶级性<strong></div>\n                  <div class="fw-bullet">绝对真理(无条件正确) vs 相对真理(有条件限制) -> 辩证统一</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、真理的检验标准\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>实践是检验真理的唯一标准<strong>：由真理本性和实践特点决定</div>\n                  <div class="fw-bullet">实践标准：确定性(能检验) + 不确定性(有局限)</div>\n                  <div class="fw-bullet">逻辑证明是重要补充，但不能代替实践标准</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、真理与价值的辩证统一\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">价值：客体对主体需要的满足(客观性+主体性+社会历史性+多维性)</div>\n                  <div class="fw-bullet">真理原则(按本来面目) + 价值原则(按人的需要) -> 统一于实践</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c2s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c2s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 认识世界和改造世界\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c2s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、认识世界的根本目的在于改造世界\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">改造客观世界 + 改造主观世界 -> 统一于<strong>实践<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、一切从实际出发，实事求是\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">思想路线：一切从实际出发 -> 理论联系实际 -> <strong>实事求是<strong>(核心) -> 实践中检验和发展真理</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c2s2sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c2s2sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、坚持守正创新\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>守正<strong>：坚持正确方向；<strong>创新<strong>：勇于突破；实践创新是基础，理论创新是先导</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c3">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c3\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第三章 人类社会及其发展规律\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c3s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c3s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 人类社会的存在与发展\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c3s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、社会存在与社会意识\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>社会存在<strong> = 地理环境 + 人口因素 + <strong>物质生产方式<strong>(决定因素)</div>\n                  <div class="fw-bullet"><strong>社会意识<strong> = 社会心理 + 社会意识形式</div>\n                  <div class="fw-bullet"><strong>社会存在决定社会意识<strong>，社会意识反作用于社会存在(相对独立性)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、社会基本矛盾及其运动规律\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>生产力<strong> = 劳动资料(工具是标志) + 劳动对象 + 劳动者(最活跃)</div>\n                  <div class="fw-bullet"><strong>生产关系<strong> = 生产资料所有制(核心) + 分配关系 + 地位关系</div>\n                  <div class="fw-bullet">生产力 决定 生产关系；生产关系 反作用于 生产力</div>\n                  <div class="fw-bullet"><strong>经济基础<strong> = 占统治地位的生产关系总和</div>\n                  <div class="fw-bullet"><strong>上层建筑<strong> = 政治上层建筑(国家政权是核心) + 观念上层建筑(意识形态)</div>\n                  <div class="fw-bullet">经济基础 决定 上层建筑；上层建筑 反作用于 经济基础</div>\n                  <div class="fw-bullet">科学技术是<strong>第一生产力<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、人类普遍交往与世界历史的形成发展\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">交往推动<strong>世界历史<strong>形成；经济全球化不可逆转</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s0sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s0sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、社会进步与社会形态更替\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">社会形态更替：<strong>统一性<strong>(五种形态) + <strong>多样性<strong>(具体道路不同)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s0sub4">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s0sub4\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  五、文明及其多样性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">人类文明新形态：物质+政治+精神+社会+生态文明协调发展</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c3s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c3s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 社会历史发展的动力\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c3s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、社会基本矛盾在历史发展中的作用\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>社会基本矛盾<strong> = 生产力vs生产关系 + 经济基础vs上层建筑</div>\n                  <div class="fw-bullet">社会基本矛盾是社会发展的<strong>根本动力<strong>；生产力是<strong>最终决定力量<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、阶级斗争、社会革命的作用\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">阶级斗争：阶级社会发展的<strong>直接动力<strong></div>\n                  <div class="fw-bullet">社会革命：阶级斗争<strong>最高形式<strong>；根本问题是<strong>国家政权<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、科学技术在社会发展中的作用\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">科技革命是<strong>强大杠杆<strong>；双刃剑；决定性制约因素：<strong>社会制度<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s1sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s1sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、文化在社会发展中的作用\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">文化是重要精神动力；先进文化推动发展</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c3s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c3s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 人民群众在历史发展中的作用\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c3s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、人民群众是历史的创造者\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">群众史观(唯物史观) vs 英雄史观(唯心史观)</div>\n                  <div class="fw-bullet">人民群众：物质+精神财富创造者 + 社会变革决定力量</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、个人在社会历史中的作用\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">杰出人物加速或延缓历史，<strong>不能决定基本趋势<strong></div>\n                  <div class="fw-bullet">评价：<strong>历史分析方法 + 阶级分析方法<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c3s2sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c3s2sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、群众、阶级、政党、领袖的关系\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">群众 -> 阶级 -> 政党 -> 领袖</div>\n                  <div class="fw-bullet">群众路线：一切为了群众，一切依靠群众，从群众中来，到群众中去</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c4">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c4\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第四章 资本主义的本质及规律\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c4s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c4s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 商品经济和价值规律\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c4s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、商品经济的形成和发展\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">商品：用来交换的劳动产品；条件：<strong>社会分工 + 私有制<strong></div>\n                  <div class="fw-bullet"><strong>使用价值<strong>(自然属性) + <strong>价值<strong>(社会属性) = 商品二因素</div>\n                  <div class="fw-bullet"><strong>具体劳动<strong>创造使用价值；<strong>抽象劳动<strong>创造价值 -> 劳动二重性</div>\n                  <div class="fw-bullet">价值量由<strong>社会必要劳动时间<strong>决定；劳动生产率与单位商品价值量<strong>成反比<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、价值规律及其作用\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">内容：价值量由社会必要劳动时间决定，等价交换</div>\n                  <div class="fw-bullet">表现形式：<strong>价格围绕价值上下波动<strong></div>\n                  <div class="fw-bullet">积极作用：调节资源配置 + 刺激生产力 + 优胜劣汰</div>\n                  <div class="fw-bullet">消极后果：资源浪费 + 阻碍技术进步 + 收入两极分化</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、以私有制为基础的商品经济的基本矛盾\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>私人劳动 vs 社会劳动<strong>的矛盾</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s0sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s0sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、马克思劳动价值论的当代价值\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">脑力劳动和科技劳动在价值创造中的作用越来越重要</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c4s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c4s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 资本主义经济制度\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c4s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、资本主义经济制度的产生\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">资本原始积累：暴力手段使生产者与生产资料分离</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、劳动力成为商品与货币转化为资本\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>劳动力成为商品<strong>是货币转化为资本的<strong>前提<strong></div>\n                  <div class="fw-bullet">劳动力价值 = 维持再生产所需生活资料价值；使用价值创造新价值且大于自身价值</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、生产剩余价值是资本主义生产方式的绝对规律\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>剩余价值(m)<strong> = 雇佣工人创造、被资本家无偿占有、超过劳动力价值的价值</div>\n                  <div class="fw-bullet">不变资本(c)购买生产资料；可变资本(v)购买劳动力 -> 剩余价值率 = m/v</div>\n                  <div class="fw-bullet">绝对剩余价值(延长工作日) vs <strong>相对剩余价值<strong>(提高生产率)</div>\n                  <div class="fw-bullet"><strong>超额剩余价值<strong>：率先改进技术获得</div>\n                  <div class="fw-bullet">资本积累 -> 资本有机构成(c:v)提高 -> 相对人口过剩</div>\n                  <div class="fw-bullet">利润 = 剩余价值的转化形式；<strong>生产价格<strong> = 成本价格 + 平均利润</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s1sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s1sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、资本主义的基本矛盾与经济危机\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">基本矛盾：<strong>生产社会化 vs 生产资料资本主义私人占有<strong></div>\n                  <div class="fw-bullet">经济危机：<strong>生产相对过剩<strong>(相对于有支付能力的需求)</div>\n                  <div class="fw-bullet">周期性：危机->萧条->复苏->高涨</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c4s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c4s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 资本主义上层建筑\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c4s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、资本主义政治制度及其本质\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">本质：<strong>资产阶级专政<strong>；民主：形式上平等，实质上不平等</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c4s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c4s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、资本主义意识形态及其本质\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">核心：<strong>个人主义<strong>；本质：为资产阶级利益服务</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c5">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c5\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第五章 资本主义的发展及其趋势\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c5s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c5s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 垄断资本主义的形成与发展\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c5s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、资本主义从自由竞争到垄断\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">19世纪末20世纪初进入<strong>垄断阶段<strong>(帝国主义)</div>\n                  <div class="fw-bullet">垄断形成：生产集中+资本集中 -> 垄断</div>\n                  <div class="fw-bullet">垄断组织：卡特尔 -> 辛迪加 -> 托拉斯 -> 康采恩</div>\n                  <div class="fw-bullet">垄断利润 = 垄断价格 - 成本；垄断不消除竞争</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c5s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、垄断资本主义的发展\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>国家垄断资本主义<strong>：国家政权与垄断资本结合</div>\n                  <div class="fw-bullet">实质：为垄断资产阶级整体利益和长远利益服务</div>\n                  <div class="fw-bullet">垄断资本向世界扩展：<strong>资本输出<strong>(主要形式)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c5s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、经济全球化及其影响\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">表现：生产+贸易+金融+企业运营全球化</div>\n                  <div class="fw-bullet">动因：科技进步+跨国公司+市场经济普及</div>\n                  <div class="fw-bullet">影响：促进增长(正)；加剧不平衡、风险全球化(负)</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c5s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c5s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 正确认识当代资本主义的新变化\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c5s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、二战后资本主义的变化及其实质\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">变化：股权分散 + 职工参与 + 福利制度 + 国家干预 + 中间阶层扩大</div>\n                  <div class="fw-bullet">实质：<strong>未改变根本性质，未消除基本矛盾<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c5s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、当代资本主义变化的新特征\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">金融危机频繁 + 实体经济空心化 + 贫富差距扩大</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c5s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、世界大变局下资本主义的矛盾与冲突\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">两种社会制度长期并存与竞争</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c5s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c5s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 资本主义的历史地位和发展趋势\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c5s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、资本主义的历史地位\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">进步性：促进生产力、发展科技；局限性：私有制 -> 两极分化、经济危机</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c5s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c5s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、资本主义为社会主义所代替的历史必然性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">基本矛盾不可调和 -> 必然被社会主义代替(长期过程)</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c6">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c6\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第六章 社会主义的发展及其规律\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c6s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c6s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 社会主义五百年的历史进程\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c6s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、社会主义从空想到科学\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">空想社会主义：圣西门/傅立叶/欧文；局限性：没发现规律+找不到力量+没正确道路</div>\n                  <div class="fw-bullet"><strong>唯物史观+剩余价值学说<strong> -> 社会主义从空想变科学(1848《共产党宣言》)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c6s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、社会主义从理想到现实、从一国到多国\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">十月革命(1917)：第一个社会主义国家</div>\n                  <div class="fw-bullet">二战后：一国到多国；80年代末90年代初：苏联解体东欧剧变(严重挫折)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c6s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、社会主义在中国焕发出蓬勃生机\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">中国特色社会主义成为振兴世界社会主义的<strong>中流砥柱<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c6s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c6s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 科学社会主义基本原则\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c6s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、科学社会主义基本原则的主要内容\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">"两个必然"：资本主义必然灭亡、社会主义必然胜利</div>\n                  <div class="fw-bullet">无产阶级是最先进最革命的阶级</div>\n                  <div class="fw-bullet">无产阶级革命和无产阶级专政是必由之路</div>\n                  <div class="fw-bullet">生产资料公有制是社会主义经济制度的基础</div>\n                  <div class="fw-bullet">坚持无产阶级政党的领导</div>\n                  <div class="fw-bullet">通过社会主义高度发展，最终实现共产主义</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c6s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、正确把握科学社会主义基本原则\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">基本原则不能丢，运用须与<strong>各国具体国情<strong>相结合</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c6s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、科学社会主义基本原则与中国特色社会主义\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">中国特色社会主义 = 科学社会主义理论逻辑 + 中国社会发展历史逻辑的<strong>辩证统一<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c6s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c6s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 在实践中探索社会主义的发展规律\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c6s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、社会主义建设过程的长期性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">原因：生产力+制度建设+文化建设长期性</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c6s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、社会主义发展道路的多样性\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">各国国情不同 -> 道路多样性；不能照搬别国模式</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c6s2sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c6s2sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、社会主义在实践中开拓前进\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">前途光明，道路曲折</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b0c7">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b0c7\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#e74c3c"></span>\n          第七章 共产主义崇高理想及其最终实现\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b0c7s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c7s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 展望未来共产主义新社会\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c7s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c7s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、预见未来社会的方法论原则\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">在揭示一般规律基础上指明方向；在剖析旧世界中阐发新世界；不空想描绘具体细节</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c7s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c7s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、共产主义社会的基本特征\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>物质财富极大丰富，按需分配<strong></div>\n                  <div class="fw-bullet"><strong>社会关系高度和谐，精神境界极大提高<strong></div>\n                  <div class="fw-bullet"><strong>每个人自由而全面的发展<strong>(必然王国->自由王国)</div>\n                  <div class="fw-bullet">阶级消灭、国家消亡、三大差别消失</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c7s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c7s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 实现共产主义是历史发展的必然趋势\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c7s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c7s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、实现共产主义是历史发展的必然\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">社会基本矛盾运动规律决定</div>\n                  <div class="fw-bullet">"两个必然"：资产阶级灭亡和无产阶级胜利同样不可避免</div>\n                  <div class="fw-bullet">"两个决不会"：生产力全部发挥前，旧社会形态决不会灭亡</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c7s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c7s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、实现共产主义是长期的历史过程\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">需要社会主义充分发展和高度发达</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b0c7s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b0c7s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 共产主义远大理想与中国特色社会主义共同理想\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b0c7s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c7s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、坚持远大理想与共同理想的辩证统一\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">远大理想=共产主义(最终目标)；共同理想=中国特色社会主义(现阶段)</div>\n                  <div class="fw-bullet">关系：共同理想是必经阶段，远大理想是最终目标</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b0c7s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b0c7s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、坚定理想信念\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">理想信念是精神之"钙"</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class="fw-book open" id="book1">\n  <div class="fw-book-header" onclick="document.getElementById(\'book1\').classList.toggle(\'open\')">\n    <span class="fw-arrow">▶</span>\n    <span class="fw-book-icon" style="background:#2ecc71">📗</span>\n    <span class="fw-book-title">第二篇：毛泽东思想和中国特色社会主义理论体系概论</span>\n    <span class="fw-book-badge">9章</span>\n  </div>\n  <div class="fw-book-content">\n    <div class="fw-toolbar">\n      <button class="on" onclick="toggleAll(\'book1\',true,this)">展开全部</button>\n      <button onclick="toggleAll(\'book1\',false,this)">收起全部</button>\n    </div>\n    <div class="fw-tree">\n\n      <div class="fw-chapter" id="b1c0">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c0\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          导论 马克思主义中国化时代化的历史进程与理论成果\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c0s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c0s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、马克思主义中国化时代化的提出\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">1938年毛泽东六届六中全会《论新阶段》："马克思主义的中国化"</div>\n              <div class="fw-bullet">背景：教条主义导致革命受挫 -> 必须从中国实际出发</div>\n              <div class="fw-bullet">两个结合：同中国具体实际相结合 + 同中华优秀传统文化相结合</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c0s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c0s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、马克思主义中国化时代化的内涵\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">三层含义：运用立场观点方法解决中国问题 + 总结实践经验上升为理论 + 用民族语言阐述</div>\n              <div class="fw-bullet">核心：坚持马克思主义与发展马克思主义相统一</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c0s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c0s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、马克思主义中国化时代化的历史进程\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>毛泽东思想<strong>：第一次历史性飞跃(新民主主义革命+社会主义建设)</div>\n              <div class="fw-bullet"><strong>中国特色社会主义理论体系<strong>：新的飞跃(改革开放以来)</div>\n              <div class="fw-bullet"><strong>习近平新时代中国特色社会主义思想<strong>：新的飞跃(新时代)</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c0s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c0s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、马克思主义中国化时代化理论成果及其关系\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">一脉相承又与时俱进；围绕不同时代课题展开</div>\n              <div class="fw-bullet">四大时代课题：什么是社会主义/怎样建设 + 建设什么样的党/怎样建设 + 实现什么样的发展/怎样发展 + 新时代坚持和发展什么样的中国特色社会主义/怎样坚持和发展</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c1">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c1\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第一章 毛泽东思想及其历史地位\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c1s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c1s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 毛泽东思想的形成和发展\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c1s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c1s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、形成发展的历史条件\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">时代背景：战争与革命；实践基础：中国共产党领导的革命和建设实践</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c1s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c1s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、形成发展的过程\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">萌芽(大革命时期)：分清敌友，农民问题</div>\n                  <div class="fw-bullet">初步形成(土地革命时期)：<strong>农村包围城市、武装夺取政权<strong>道路</div>\n                  <div class="fw-bullet">成熟(遵义会议后到抗战)：系统阐述新民主主义革命理论</div>\n                  <div class="fw-bullet">继续发展(解放战争+新中国成立后)：社会主义改造和建设思想</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c1s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c1s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 毛泽东思想的主要内容和活的灵魂\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c1s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c1s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、毛泽东思想的主要内容\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>新民主主义革命理论<strong>：革命对象/动力/领导力量/道路</div>\n                  <div class="fw-bullet"><strong>社会主义革命和建设理论<strong>：过渡时期总路线、工业化道路</div>\n                  <div class="fw-bullet"><strong>军队建设和军事战略理论<strong>：党指挥枪、人民战争</div>\n                  <div class="fw-bullet"><strong>政策和策略理论<strong>：政策和策略是党的生命</div>\n                  <div class="fw-bullet"><strong>党的建设理论<strong>：着重从思想上建设党</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c1s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c1s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、毛泽东思想活的灵魂\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>实事求是<strong>：一切从实际出发，理论联系实际(核心)</div>\n                  <div class="fw-bullet"><strong>群众路线<strong>：一切为了群众，一切依靠群众，从群众中来，到群众中去</div>\n                  <div class="fw-bullet"><strong>独立自主<strong>：坚持独立思考，走自己的路</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c1s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c1s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 毛泽东思想的历史地位\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">马克思主义中国化时代化的<strong>第一个重大理论成果<strong></div>\n              <div class="fw-bullet"><strong>中国革命和建设的科学指南<strong></div>\n              <div class="fw-bullet"><strong>中国共产党和中国人民宝贵的精神财富<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c2">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c2\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第二章 新民主主义革命理论\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c2s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c2s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 新民主主义革命理论形成的依据\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c2s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、近代中国国情和中国革命的时代特征\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">近代中国社会性质：<strong>半殖民地半封建社会<strong></div>\n                  <div class="fw-bullet">主要矛盾：帝国主义与中华民族、封建主义与人民大众的矛盾</div>\n                  <div class="fw-bullet">革命性质：资产阶级民主革命(新旧区别：领导权)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c2s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、新民主主义革命理论的实践基础\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">旧民主主义革命失败的教训 + 新民主主义革命实践探索</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c2s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c2s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 新民主主义革命的总路线和基本纲领\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c2s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、新民主主义革命的总路线\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">总路线：<strong>无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命<strong></div>\n                  <div class="fw-bullet">革命对象：帝国主义(首要对象)、封建主义、官僚资本主义("三座大山")</div>\n                  <div class="fw-bullet">革命动力：无产阶级(领导力量) + 农民(主力军) + 城市小资产阶级 + 民族资产阶级</div>\n                  <div class="fw-bullet">革命领导权：<strong>无产阶级<strong>(通过共产党)掌握领导权是革命胜利的根本保证</div>\n                  <div class="fw-bullet">革命性质：<strong>新式的特殊的资产阶级民主革命<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c2s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、新民主主义的基本纲领\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">政治纲领：建立无产阶级领导的、工农联盟为基础的、各革命阶级联合专政的民主共和国</div>\n                  <div class="fw-bullet">经济纲领：没收地主土地归农民所有 + 没收官僚资本归国家所有 + 保护民族工商业</div>\n                  <div class="fw-bullet">文化纲领：无产阶级领导的、人民大众的、<strong>反帝反封建<strong>的文化(民族的、科学的、大众的)</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c2s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c2s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 新民主主义革命的道路和基本经验\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c2s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、新民主主义革命的道路\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">道路：<strong>农村包围城市、武装夺取政权<strong></div>\n                  <div class="fw-bullet">必然性：中国国情决定(农民占多数、敌人占据城市、农村有回旋余地)</div>\n                  <div class="fw-bullet">内容：土地革命(基本内容) + 武装斗争(主要形式) + 农村根据地建设(战略阵地)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c2s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、新民主主义革命的三大法宝\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>统一战线<strong>：团结一切可以团结的力量(工农联盟为基础)</div>\n                  <div class="fw-bullet"><strong>武装斗争<strong>：中国革命的主要形式</div>\n                  <div class="fw-bullet"><strong>党的建设<strong>：思想建设放在首位 -> 三大法宝的核心</div>\n                  <div class="fw-bullet">三者关系：统一战线和武装斗争是武器，党的组织是掌握武器的战士</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c2s2sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c2s2sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、新民主主义革命理论的意义\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">揭示了革命规律，指导革命胜利；丰富发展了马克思主义</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c3">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c3\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第三章 社会主义改造理论\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c3s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c3s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 从新民主主义到社会主义的转变\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c3s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c3s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、新民主主义社会是一个过渡性的社会\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">五种经济成分并存：国营经济(领导地位) + 合作社经济 + 个体经济 + 私人资本主义 + 国家资本主义</div>\n                  <div class="fw-bullet">社会性质：<strong>过渡性社会<strong>，不是独立的社会形态</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c3s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c3s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、党在过渡时期的总路线及其依据\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">总路线：<strong>一化三改<strong> = 社会主义工业化(主体) + 农业/手工业/资本主义工商业改造(两翼)</div>\n                  <div class="fw-bullet">过渡时期：1949-1956，"相当长的时期"</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c3s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c3s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 社会主义改造道路和历史经验\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c3s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c3s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、适合中国特点的社会主义改造道路\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>农业改造<strong>：互助组 -> 初级社(半社会主义) -> 高级社(社会主义)；自愿互利、典型示范</div>\n                  <div class="fw-bullet"><strong>手工业改造<strong>：供销合作小组 -> 供销合作社 -> 生产合作社</div>\n                  <div class="fw-bullet"><strong>资本主义工商业改造<strong>：和平赎买 + 国家资本主义(委托加工->公私合营->全行业公私合营)</div>\n                  <div class="fw-bullet">对资本家："团结、教育、改造"，企业改造与人的改造相结合</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c3s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c3s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、社会主义改造的历史经验\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>同时并举<strong>(工业化与改造同时进行)；<strong>逐步过渡<strong>；<strong>和平改造<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c3s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c3s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 社会主义基本制度在中国的确立\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c3s2sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c3s2sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、社会主义基本制度的确立及其理论根据\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">1956年改造基本完成 -> 社会主义基本制度确立</div>\n                  <div class="fw-bullet">标志：生产资料公有制成为社会经济基础</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c3s2sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c3s2sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、确立社会主义基本制度的重大意义\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了<strong>根本政治前提和制度基础<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c4">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c4\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第四章 社会主义建设道路初步探索的理论成果\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c4s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c4s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 初步探索的重要理论成果\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c4s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c4s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、调动一切积极因素为社会主义事业服务\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">《论十大关系》：调动国内外一切积极因素，为社会主义服务(基本方针)</div>\n                  <div class="fw-bullet">十大关系围绕一个基本方针：<strong>把我国建设成为一个强大的社会主义国家<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c4s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c4s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、正确认识和处理社会主义社会矛盾的思想\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">《关于正确处理人民内部矛盾的问题》</div>\n                  <div class="fw-bullet">社会主义社会基本矛盾：生产力vs生产关系 + 经济基础vs上层建筑(非对抗)</div>\n                  <div class="fw-bullet"><strong>两类矛盾<strong>：敌我矛盾(对抗性/专政) + <strong>人民内部矛盾<strong>(非对抗性/民主) -> 正确处理后者是主题</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c4s0sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c4s0sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、走中国工业化道路的思想\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">以农业为基础、工业为主导，<strong>农轻重为序<strong>发展国民经济</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c4s0sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c4s0sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、初步探索的其他理论成果\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">社会主义两阶段：不发达 + 比较发达；"四个现代化"；商品经济等</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c4s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c4s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 初步探索的意义和经验教训\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">意义：巩固发展社会主义制度 + 为开创中国特色社会主义提供宝贵经验和理论准备</div>\n              <div class="fw-bullet">教训：不能超越发展阶段 + 必须以经济建设为中心 + 必须健全民主法治 + 必须坚持对外开放</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c5">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c5\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第五章 中国特色社会主义理论体系的形成发展\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c5s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c5s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 形成发展的社会历史条件\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">国际背景：和平与发展成为时代主题 + 经济全球化深入发展</div>\n              <div class="fw-bullet">历史条件：新中国成立以来正反两方面经验总结</div>\n              <div class="fw-bullet">实践基础：改革开放和社会主义现代化建设实践</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c5s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c5s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 形成发展过程\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>邓小平理论<strong>(十一届三中全会后)：开创中国特色社会主义</div>\n              <div class="fw-bullet">"三个代表"重要思想(十三届四中全会后)：推向21世纪</div>\n              <div class="fw-bullet"><strong>科学发展观<strong>(十六大后)：新形势下坚持和发展</div>\n              <div class="fw-bullet"><strong>习近平新时代中国特色社会主义思想<strong>(十八大以来)：新时代新篇章</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c6">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c6\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第六章 邓小平理论\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c6s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c6s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 邓小平理论首要的基本理论问题和精髓\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c6s0sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s0sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、首要的基本理论问题\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>什么是社会主义、怎样建设社会主义<strong></div>\n                  <div class="fw-bullet">社会主义本质：解放生产力、发展生产力、消灭剥削、消除两极分化、最终达到<strong>共同富裕<strong></div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s0sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s0sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、邓小平理论的精髓\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet"><strong>解放思想、实事求是<strong></div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c6s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 邓小平理论的主要内容\n            </div>\n            <div class="fw-section-body">\n\n              <div class="fw-section" id="b1c6s1sub0">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub0\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  一、社会主义初级阶段理论和党的基本路线\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">社会主义初级阶段：我国最大国情、最大实际(两层含义：已是社会主义+还处于初级阶段)</div>\n                  <div class="fw-bullet">基本路线：<strong>一个中心、两个基本点<strong> = 以经济建设为中心 + 坚持四项基本原则 + 坚持改革开放</div>\n                  <div class="fw-bullet">"三步走"战略：温饱(1990) -> 小康(2000) -> 基本现代化(21世纪中叶)</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s1sub1">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub1\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  二、社会主义根本任务和发展战略理论\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">根本任务：<strong>发展生产力<strong>；"发展才是硬道理"</div>\n                  <div class="fw-bullet">科技是第一生产力</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s1sub2">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub2\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  三、社会主义改革开放和社会主义市场经济理论\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">改革是<strong>第二次革命<strong>，是社会主义制度的自我完善</div>\n                  <div class="fw-bullet">计划和市场都是<strong>经济手段<strong>，社会主义也可以搞市场经济</div>\n                  <div class="fw-bullet">对外开放：<strong>基本国策<strong>；经济特区是"窗口"</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s1sub3">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub3\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  四、"两手抓，两手都要硬"\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">物质文明和精神文明都要搞好</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s1sub4">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub4\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  五、"一国两制"与祖国统一\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">一个中国前提下，国家主体实行社会主义，港澳台保持原有制度长期不变</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s1sub5">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub5\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  六、中国特色社会主义外交和国际战略\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">时代主题：<strong>和平与发展<strong>；独立自主的和平外交政策</div>\n                </div>\n              </div>\n\n              <div class="fw-section" id="b1c6s1sub6">\n                <div class="fw-section-header" onclick="document.getElementById(\'b1c6s1sub6\').classList.toggle(\'open\')" style="font-size:0.8em;padding-left:8px;">\n                  <span class="fw-arrow">▶</span>\n                  <span class="fw-section-dot"></span>\n                  七、党的建设理论\n                </div>\n                <div class="fw-section-body" style="padding-left:16px;">\n                  <div class="fw-bullet">坚持党的领导、改善党的领导</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c6s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c6s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 邓小平理论的历史地位\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>马克思列宁主义、毛泽东思想的继承和发展<strong></div>\n              <div class="fw-bullet"><strong>中国特色社会主义理论体系的开篇之作<strong></div>\n              <div class="fw-bullet"><strong>改革开放和社会主义现代化建设的科学指南<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c7">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c7\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第七章 "三个代表"重要思想\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c7s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c7s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 "三个代表"重要思想的核心观点\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>始终代表中国先进生产力的发展要求<strong></div>\n              <div class="fw-bullet"><strong>始终代表中国先进文化的前进方向<strong></div>\n              <div class="fw-bullet"><strong>始终代表中国最广大人民的根本利益<strong></div>\n              <div class="fw-bullet">"三个代表"是统一的整体：发展生产力是基础、先进文化是灵魂、人民利益是目的</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c7s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c7s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 "三个代表"重要思想的主要内容\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">发展是党执政兴国的<strong>第一要务<strong></div>\n              <div class="fw-bullet">建立<strong>社会主义市场经济体制<strong>(改革目标)</div>\n              <div class="fw-bullet">全面建设小康社会(新世纪头20年目标)</div>\n              <div class="fw-bullet">建设社会主义政治文明(党的领导+人民当家作主+依法治国统一)</div>\n              <div class="fw-bullet">"引进来"和"走出去"相结合的对外开放战略</div>\n              <div class="fw-bullet">推进党的建设新的<strong>伟大工程<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c7s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c7s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 "三个代表"重要思想的历史地位\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">中国特色社会主义理论体系的丰富发展</div>\n              <div class="fw-bullet">加强和改进党的建设的强大理论武器</div>\n              <div class="fw-bullet">进一步回答了什么是社会主义/怎样建设社会主义，创造性地回答了<strong>建设什么样的党/怎样建设党<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b1c8">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b1c8\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#2ecc71"></span>\n          第八章 科学发展观\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b1c8s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c8s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第一节 科学发展观的科学内涵\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>第一要义<strong>：推动经济社会发展</div>\n              <div class="fw-bullet"><strong>核心立场<strong>：以人为本</div>\n              <div class="fw-bullet"><strong>基本要求<strong>：全面协调可持续</div>\n              <div class="fw-bullet"><strong>根本方法<strong>：统筹兼顾</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c8s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c8s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第二节 科学发展观的主要内容\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">加快转变经济发展方式(主攻方向：调整经济结构)</div>\n              <div class="fw-bullet">发展社会主义民主政治(协商民主)</div>\n              <div class="fw-bullet">推进社会主义文化强国建设(社会主义核心价值体系)</div>\n              <div class="fw-bullet">构建社会主义和谐社会(学有所教、劳有所得、病有所医、老有所养、住有所居)</div>\n              <div class="fw-bullet">推进生态文明建设(建设资源节约型、环境友好型社会)</div>\n              <div class="fw-bullet">全面提高党的建设科学化水平(执政能力+先进性+纯洁性)</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b1c8s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b1c8s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              第三节 科学发展观的历史地位\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">中国特色社会主义理论体系在新世纪新阶段的接续发展</div>\n              <div class="fw-bullet">全面建设小康社会、加快推进社会主义现代化的<strong>根本指针<strong></div>\n              <div class="fw-bullet">深刻认识和回答了新形势下<strong>实现什么样的发展、怎样发展<strong>的重大问题</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class="fw-book open" id="book2">\n  <div class="fw-book-header" onclick="document.getElementById(\'book2\').classList.toggle(\'open\')">\n    <span class="fw-arrow">▶</span>\n    <span class="fw-book-icon" style="background:#3498db">📘</span>\n    <span class="fw-book-title">第三篇：习近平新时代中国特色社会主义思想概论</span>\n    <span class="fw-book-badge">18章</span>\n  </div>\n  <div class="fw-book-content">\n    <div class="fw-toolbar">\n      <button class="on" onclick="toggleAll(\'book2\',true,this)">展开全部</button>\n      <button onclick="toggleAll(\'book2\',false,this)">收起全部</button>\n    </div>\n    <div class="fw-tree">\n\n      <div class="fw-chapter" id="b2c0">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c0\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          导论\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c0s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c0s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、习近平新时代中国特色社会主义思想创立的时代背景\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>世界百年未有之大变局加速演进<strong>：和平发展合作共赢不可阻挡，"东升西降"趋势显著</div>\n              <div class="fw-bullet"><strong>中华民族伟大复兴进入关键时期<strong>：船到中流浪更急、人到半山路更陡</div>\n              <div class="fw-bullet"><strong>中国式现代化全面推进拓展<strong>：创造人类文明新形态</div>\n              <div class="fw-bullet"><strong>科学社会主义在21世纪中国焕发蓬勃生机<strong>：中国特色社会主义成为振兴世界社会主义的旗帜</div>\n              <div class="fw-bullet"><strong>中国共产党自我革命开辟新境界<strong>：跳出治乱兴衰历史周期率的第二个答案</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c0s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c0s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、习近平新时代中国特色社会主义思想是"两个结合"的重大成果\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"两个结合" = 同中国具体实际相结合 + 同中华优秀传统文化相结合</div>\n              <div class="fw-bullet">"第二个结合"是又一次思想解放</div>\n              <div class="fw-bullet">魂脉(马克思主义) + 根脉(中华优秀传统文化) 内在贯通、相互成就</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c0s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c0s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、习近平新时代中国特色社会主义思想是完整的科学体系\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"十个明确"：主体内容 = 四梁八柱(集中体现主要观点和基本精神)</div>\n              <div class="fw-bullet">"十四个坚持"：基本方略 = 治国理政各方面理论分析和政策指导</div>\n              <div class="fw-bullet">"十三个方面成就"：实践总结 = 全景式展示理论与实践成果</div>\n              <div class="fw-bullet">"六个必须坚持"：世界观和方法论 = 人民至上/自信自立/守正创新/问题导向/系统观念/胸怀天下</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c0s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c0s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、习近平新时代中国特色社会主义思想的历史地位\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>当代中国马克思主义、二十一世纪马克思主义<strong></div>\n              <div class="fw-bullet"><strong>中华文化和中国精神的时代精华<strong></div>\n              <div class="fw-bullet">实现马克思主义中国化时代化<strong>新的飞跃<strong></div>\n              <div class="fw-bullet">全党全国人民实现中华民族伟大复兴的<strong>行动指南<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c0s4">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c0s4\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              五、深刻领悟"两个确立"的决定性意义\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">两个确立：确立习近平同志党中央的核心、全党的核心地位 + 确立习近平新时代中国特色社会主义思想的指导地位</div>\n              <div class="fw-bullet">决定性的因素：新时代取得历史性成就、发生历史性变革的<strong>决定性因素<strong></div>\n              <div class="fw-bullet">最大确定性、最大底气、最大保证</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c0s5">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c0s5\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              六、学好用好习近平新时代中国特色社会主义思想\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">教材结构：导论 + 17章(1-5章阐述根本问题/6-12章阐述总体布局/13-17章阐述保障条件)</div>\n              <div class="fw-bullet">学习方法：坚定理想信念 + 提高理论水平 + 增强实践能力</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c1">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c1\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第一章 新时代坚持和发展中国特色社会主义\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c1s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c1s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、中国特色社会主义是历史和人民的选择\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">中国特色社会主义是党和人民历经千辛万苦、付出巨大代价取得的<strong>根本成就<strong></div>\n              <div class="fw-bullet">"四个得来"：改革开放40多年实践 + 新中国成立70多年探索 + 党领导伟大社会革命100多年 + 近代以来180多年历史进程 + 世界社会主义500多年 + 中华文明5000多年传承</div>\n              <div class="fw-bullet">中国特色社会主义是社会主义而不是其他什么主义(科学社会主义理论逻辑+中国社会发展历史逻辑辩证统一)</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c1s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c1s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、中国特色社会主义新时代的科学内涵\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">新时代是我国发展<strong>新的历史方位<strong></div>\n              <div class="fw-bullet">新时代的内涵(五个"是")：承前启后继往开来、决胜全面小康/建设现代化强国、逐步实现共同富裕、实现民族复兴中国梦、为人类作出更大贡献的时代</div>\n              <div class="fw-bullet">"三个意味着"：近代以来从站起来富起来到强起来的飞跃 + 科学社会主义在21世纪中国焕发活力 + 为发展中国家提供全新选择</div>\n              <div class="fw-bullet">社会主要矛盾转化：<strong>人民日益增长的美好生活需要 vs 不平衡不充分的发展<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c1s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c1s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、新时代伟大变革及其里程碑意义\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">历史性成就和历史性变革：经济、政治、文化、社会、生态文明、国防军队、国家安全、外交、党建各领域</div>\n              <div class="fw-bullet">"四个全面"中的第一个全面：全面建设社会主义现代化国家</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c1s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c1s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、全面贯彻党的基本理论、基本路线、基本方略\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">坚定"四个自信"：<strong>道路自信<strong>(实现途径) + <strong>理论自信<strong>(行动指南) + <strong>制度自信<strong>(根本保障) + <strong>文化自信<strong>(精神力量)</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c1s4">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c1s4\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              五、统筹推进"五位一体"总体布局和协调推进"四个全面"战略布局\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"五位一体"：经济建设 + 政治建设 + 文化建设 + 社会建设 + 生态文明建设</div>\n              <div class="fw-bullet">"四个全面"：全面建设社会主义现代化国家 + 全面深化改革 + 全面依法治国 + 全面从严治党</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c2">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c2\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第二章 以中国式现代化全面推进中华民族伟大复兴\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c2s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c2s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、中华民族伟大复兴中国梦\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">本质：<strong>国家富强、民族振兴、人民幸福<strong></div>\n              <div class="fw-bullet">实现路径：中国道路 + 中国精神 + 中国力量</div>\n              <div class="fw-bullet">两步走：2035年基本实现现代化 -> 本世纪中叶建成<strong>富强民主文明和谐美丽<strong>的社会主义现代化强国</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c2s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c2s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、中国式现代化是强国建设、民族复兴的唯一正确道路\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">中国式现代化的五个中国特色：<strong>人口规模巨大 + 全体人民共同富裕 + 物质文明和精神文明相协调 + 人与自然和谐共生 + 走和平发展道路<strong></div>\n              <div class="fw-bullet">中国式现代化的本质要求：坚持党的领导 + 坚持中国特色 + 高质量发展 + 全过程人民民主 + 丰富人民精神世界 + 实现共同富裕 + 促进人与自然和谐共生 + 构建人类命运共同体 + 创造人类文明新形态</div>\n              <div class="fw-bullet">中国式现代化创造了<strong>人类文明新形态<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c3">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c3\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第三章 坚持党的全面领导\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c3s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c3s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、中国共产党领导是中国特色社会主义最本质的特征\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"十个明确"之首：中国特色社会主义最本质的特征 = 中国共产党领导</div>\n              <div class="fw-bullet">中国特色社会主义制度的最大优势 = 中国共产党领导</div>\n              <div class="fw-bullet">党是<strong>最高政治领导力量<strong></div>\n              <div class="fw-bullet">党政军民学，东西南北中，<strong>党是领导一切的<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c3s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c3s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、坚持党对一切工作的领导\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"两个维护"：坚决维护习近平总书记党中央的核心、全党的核心地位 + 坚决维护党中央权威和集中统一领导</div>\n              <div class="fw-bullet">"四个意识"：政治意识、大局意识、核心意识、看齐意识</div>\n              <div class="fw-bullet">党的领导是<strong>全面的、系统的、整体的<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c3s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c3s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、健全总揽全局、协调各方的党的领导制度体系\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">完善党中央对重大工作的领导体制；完善党领导各项事业的具体制度</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c4">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c4\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第四章 坚持以人民为中心\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c4s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c4s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、人民是历史的创造者\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">以人民为中心是<strong>根本立场<strong>；"江山就是人民，人民就是江山"</div>\n              <div class="fw-bullet">"六个必须坚持"之首：<strong>坚持人民至上<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c4s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c4s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、坚持人民主体地位\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">坚持<strong>人民当家作主<strong>；发展全过程人民民主</div>\n              <div class="fw-bullet"><strong>共同富裕<strong>是中国式现代化的重要特征</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c4s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c4s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、不断实现人民对美好生活的向往\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">以人民为中心的发展思想：发展为了人民、发展依靠人民、发展成果由人民共享</div>\n              <div class="fw-bullet">扎实推进<strong>共同富裕<strong>：到2035年全体人民共同富裕取得更为明显的实质性进展</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c5">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c5\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第五章 全面深化改革开放\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c5s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c5s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、改革开放是决定当代中国命运的关键一招\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">改革开放是<strong>关键一招<strong>；只有进行时，没有完成时</div>\n              <div class="fw-bullet">全面深化改革总目标：<strong>完善和发展中国特色社会主义制度 + 推进国家治理体系和治理能力现代化<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c5s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c5s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、全面深化改革的方向、立场和原则\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">方向：中国特色社会主义；立场：人民立场；原则：加强党的领导</div>\n              <div class="fw-bullet">使<strong>市场在资源配置中起决定性作用<strong>，更好发挥政府作用</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c5s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c5s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、推进高水平对外开放\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">构建<strong>新发展格局<strong>：以国内大循环为主体、国内国际双循环相互促进</div>\n              <div class="fw-bullet">新发展理念：<strong>创新、协调、绿色、开放、共享<strong></div>\n              <div class="fw-bullet">高质量发展是全面建设社会主义现代化国家的<strong>首要任务<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c6">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c6\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第六章 推动高质量发展\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c6s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c6s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、进入新发展阶段\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">新发展阶段：全面建设社会主义现代化国家、向第二个百年奋斗目标进军</div>\n              <div class="fw-bullet">贯彻新发展理念(创新/协调/绿色/开放/共享)是关系我国发展全局的<strong>深刻变革<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c6s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c6s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、构建新发展格局\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">国内大循环为主体、国内国际双循环相互促进</div>\n              <div class="fw-bullet">关键在于<strong>经济循环畅通无阻<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c6s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c6s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、建设现代化经济体系\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">大力发展<strong>实体经济<strong>；建设制造强国、质量强国、网络强国、数字中国</div>\n              <div class="fw-bullet">全面推进乡村振兴；促进区域协调发展</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c7">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c7\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第七章 社会主义现代化建设的教育、科技、人才战略\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c7s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c7s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持教育优先发展、科技自立自强、人才引领驱动\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑<strong></div>\n              <div class="fw-bullet">科技是第一生产力、人才是第一资源、创新是第一动力</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c7s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c7s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、办好人民满意的教育\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">教育的根本问题：培养什么人、怎样培养人、为谁培养人</div>\n              <div class="fw-bullet">立德树人是<strong>根本任务<strong>；培养德智体美劳全面发展的社会主义建设者和接班人</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c7s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c7s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、加快实现高水平科技自立自强\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">坚决打赢关键核心技术攻坚战；强化国家战略科技力量</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c7s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c7s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、深入实施新时代人才强国战略\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">聚天下英才而用之</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c8">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c8\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第八章 发展全过程人民民主\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c8s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c8s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚定不移走中国特色社会主义政治发展道路\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">全过程人民民主是<strong>社会主义民主政治的本质属性<strong></div>\n              <div class="fw-bullet">党的领导 + 人民当家作主 + 依法治国 <strong>有机统一<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c8s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c8s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、健全人民当家作主制度体系\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">根本政治制度：<strong>人民代表大会制度<strong></div>\n              <div class="fw-bullet">基本政治制度：中国共产党领导的多党合作和政治协商制度 + 民族区域自治制度 + 基层群众自治制度</div>\n              <div class="fw-bullet">全过程人民民主实现了过程民主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志相统一</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c8s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c8s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、全面发展协商民主\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">协商民主是实践全过程人民民主的重要形式</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c8s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c8s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、巩固和发展最广泛的爱国统一战线\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">统一战线是凝聚人心、汇聚力量的<strong>强大法宝<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c9">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c9\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第九章 全面依法治国\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c9s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c9s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持中国特色社会主义法治道路\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">全面依法治国是<strong>国家治理的一场深刻革命<strong></div>\n              <div class="fw-bullet">总目标：建设中国特色社会主义法治体系 + 建设社会主义法治国家</div>\n              <div class="fw-bullet">核心要义：坚持党的领导 + 坚持中国特色社会主义制度 + 贯彻中国特色社会主义法治理论</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c9s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c9s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、建设中国特色社会主义法治体系\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">完备的法律规范体系 + 高效的法治实施体系 + 严密的法治监督体系 + 有力的法治保障体系 + 完善的党内法规体系</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c9s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c9s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、加快建设法治中国\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>科学立法、严格执法、公正司法、全民守法<strong>(新十六字方针)</div>\n              <div class="fw-bullet">坚持依法治国、依法执政、依法行政共同推进；法治国家、法治政府、法治社会一体建设</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c10">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c10\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十章 建设社会主义文化强国\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c10s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c10s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持中国特色社会主义文化发展道路\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">坚定<strong>文化自信<strong>：文化自信是更基础、更广泛、更深厚的自信</div>\n              <div class="fw-bullet">意识形态工作是为国家立心、为民族立魂的工作</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c10s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c10s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、建设具有强大凝聚力和引领力的社会主义意识形态\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">坚持马克思主义在意识形态领域指导地位的根本制度</div>\n              <div class="fw-bullet">广泛践行<strong>社会主义核心价值观<strong>(国家层面：富强民主文明和谐 / 社会层面：自由平等公正法治 / 个人层面：爱国敬业诚信友善)</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c10s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c10s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、推动中华优秀传统文化创造性转化、创新性发展\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"第二个结合"的重大意义：让马克思主义扎根中国</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c10s3">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c10s3\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              四、繁荣发展文化事业和文化产业\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">讲好中国故事，传播好中国声音</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c11">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c11\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十一章 以保障和改善民生为重点加强社会建设\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c11s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c11s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、增进民生福祉是发展的根本目的\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>在发展中保障和改善民生<strong></div>\n              <div class="fw-bullet">坚持尽力而为、量力而行</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c11s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c11s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、加强和创新社会治理\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">建设人人有责、人人尽责、人人享有的<strong>社会治理共同体<strong></div>\n              <div class="fw-bullet">坚持和发展新时代"枫桥经验"</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c12">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c12\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十二章 建设社会主义生态文明\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c12s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c12s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持人与自然和谐共生\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"绿水青山就是<strong>金山银山<strong>"</div>\n              <div class="fw-bullet">人与自然和谐共生是中国式现代化的<strong>鲜明特点<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c12s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c12s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、推动绿色发展\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>碳达峰碳中和<strong>：2030年前碳达峰、2060年前碳中和</div>\n              <div class="fw-bullet">推动形成<strong>绿色生产方式和生活方式<strong></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c13">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c13\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十三章 维护和塑造国家安全\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c13s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c13s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持总体国家安全观\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">国家安全是民族复兴的<strong>根基<strong></div>\n              <div class="fw-bullet">总体国家安全观：以人民安全为宗旨 + 以政治安全为根本 + 以经济安全为基础</div>\n              <div class="fw-bullet">统筹发展和安全</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c13s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c13s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、构建统筹各领域安全的新安全格局\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>政治安全<strong>(首要) + 经济安全 + 文化安全 + 社会安全 + 生态安全 + 网络安全 + 军事安全等</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c14">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c14\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十四章 建设巩固国防和强大人民军队\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c14s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c14s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、党在新时代的强军目标\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">建设一支<strong>听党指挥、能打胜仗、作风优良<strong>的人民军队，把人民军队建设成为<strong>世界一流军队<strong></div>\n              <div class="fw-bullet">听党指挥是灵魂、能打胜仗是核心、作风优良是保证</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c14s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c14s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、坚持党对人民军队的绝对领导\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"<strong>党指挥枪<strong>"是人民军队的建军之本、强军之魂</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c15">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c15\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十五章 坚持"一国两制"和推进祖国完全统一\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c15s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c15s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持和完善"一国两制"\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"一国两制"是港澳回归后保持长期繁荣稳定的<strong>最佳制度安排<strong></div>\n              <div class="fw-bullet">中央政府对港澳拥有<strong>全面管治权<strong></div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c15s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c15s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、推进祖国完全统一\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet"><strong>和平统一、一国两制<strong>方针</div>\n              <div class="fw-bullet">坚持一个中国原则和"九二共识"</div>\n              <div class="fw-bullet">解决台湾问题是中国人自己的事，绝不承诺放弃使用武力</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c16">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c16\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十六章 中国特色大国外交和推动构建人类命运共同体\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c16s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c16s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、坚持独立自主的和平外交政策\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">中国特色大国外交要服务民族复兴、促进人类进步</div>\n              <div class="fw-bullet">坚持走和平发展道路，反对一切形式的霸权主义和强权政治</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c16s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c16s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、推动构建人类命运共同体\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">核心理念：建设<strong>持久和平、普遍安全、共同繁荣、开放包容、清洁美丽<strong>的世界</div>\n              <div class="fw-bullet">弘扬<strong>和平、发展、公平、正义、民主、自由<strong>的全人类共同价值</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c16s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c16s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、推动共建"一带一路"高质量发展\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">共商、共建、共享原则</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="fw-chapter" id="b2c17">\n        <div class="fw-chapter-header" onclick="document.getElementById(\'b2c17\').classList.toggle(\'open\')">\n          <span class="fw-arrow">▶</span>\n          <span class="fw-chapter-dot" style="background:#3498db"></span>\n          第十七章 全面从严治党\n        </div>\n        <div class="fw-chapter-body">\n\n          <div class="fw-section" id="b2c17s0">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c17s0\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              一、全面从严治党是党永葆生机活力的必由之路\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">全面从严治党是新时代党的建设的<strong>鲜明主题<strong></div>\n              <div class="fw-bullet"><strong>自我革命<strong>是跳出治乱兴衰历史周期率的第二个答案</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c17s1">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c17s1\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              二、新时代党的建设总要求\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把<strong>制度建设<strong>贯穿其中</div>\n              <div class="fw-bullet">政治建设是党的<strong>根本性建设<strong></div>\n              <div class="fw-bullet">反腐败斗争：不敢腐、不能腐、不想腐一体推进</div>\n            </div>\n          </div>\n\n          <div class="fw-section" id="b2c17s2">\n            <div class="fw-section-header" onclick="document.getElementById(\'b2c17s2\').classList.toggle(\'open\')">\n              <span class="fw-arrow">▶</span>\n              <span class="fw-section-dot"></span>\n              三、以伟大自我革命引领伟大社会革命\n            </div>\n            <div class="fw-section-body">\n              <div class="fw-bullet">"四个伟大"：伟大斗争 + <strong>伟大工程<strong>(决定性作用) + 伟大事业 + 伟大梦想</div>\n              <div class="fw-bullet">全面从严治党永远在路上，党的自我革命永远在路上</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>';
